window.AUTH=window.AUTH||{};window.AUTH["17-8995"]={"d":"17-8995","id":"2018/17-8995","n":"Mont v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner Jason Mont","date":"2018-12-17","url":"https://www.supremecourt.gov/DocketPDF/17/17-8995/76423/20181217130549048_Petitioner%20Merit%20Brief.pdf","side":"pet","n":55},{"k":"respondent","label":"Brief of respondent United States","date":"2019-01-16","url":"https://www.supremecourt.gov/DocketPDF/17/17-8995/80741/20190116135521163_17-8995bsUnitedStates.pdf","side":"res","n":86},{"k":"reply","label":"Reply of petitioner Jason Mont","date":"2019-02-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-8995/88428/20190214140922629_Reply%20Brief.pdf","side":"pet","n":35}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-8995_new_097c.pdf","tr":true,"items":[{"t":"case","label":"Carr v. United States","cite":"560 U.S. 438","y":2010,"id":"2009/08-1301","sc":1,"op":2,"sum":"The Court held that the Sex Offender and Registration Act does not apply to sex offenders' interstate travel that occurred before the Act's effective date.","sumSrc":"Oyez","by":{"0":"19, 21","1":"32"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"0":"23"}},{"t":"case","label":"Deal v. United States","cite":"508 U.S. 129","y":1993,"id":"1992/91-8199","sc":1,"sum":"The Court held that Deal's second through sixth convictions in a single proceeding arose \"in the case of his second or subsequent conviction\" within the meaning of section 924(c)(1), finding that the statute was not ambiguous.","sumSrc":"Oyez","by":{"0":"26","1":"18, 41"}},{"t":"case","label":"Dolan v. United States","cite":"560 U.S. 605","y":2010,"id":"2009/09-367","sc":1,"op":1,"sum":"The Court held that federal courts may enter a restitution order beyond the time prescribed under the Mandatory Victims Restitution Act if certain qualifications are met.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"Dole Food Co. v. Patrickson","cite":"538 U.S. 468","y":2003,"id":"2002/01-593","sc":1,"sum":"The Court held, 7-2, that a foreign state must itself own a majority of the shares of a corporation if the corporation is to be deemed an instrumentality of the state under the provisions of the FSIA and, 9-0, that instrumentality status is determined at the time of the filing of the complaint.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"General Dynamics Land Sys. v. Cline","cite":"540 U.S. 581","y":2004,"id":"2003/02-1080","sc":1,"sum":"Justice David H. Souter delivered the Court's 6-3 opinion that the Age Discrimination in Employment Act's \"text, structure, purpose, history, and relationship to other federal statutes show that the statute does not mean to stop an employer from favoring an older employee over a younger one.\" The Court cited a long-held understanding of the \"ADEA as a remedy for unfair preference based on relative youth, leaving complaints of the relatively young outside the statutory concern.\" The Court also noted the findings section of the act included no evidence of younger workers being discriminated against in favor of older workers.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Gonzalez v. Thaler","cite":"565 U.S. 134","y":2012,"id":"2011/10-895","sc":1,"sum":"The Court held that a prisoner who does not seek review in a state’s highest court faces final judgment for the purposes of Section 2244(d)(1)(A) upon “expiration of the time for seeking such review.”","sumSrc":"Oyez","by":{"0":"31, 32"}},{"t":"case","label":"Good Samaritan Hospital v. Shalala","cite":"508 U.S. 402","y":1993,"id":"1992/91-2079","sc":1,"sum":"Title 42 U. S. C. § 1395f(b)(1) requires the Secretary of Health and Human Services to reimburse the lesser of the \"customary charges\" or the \"reasonable cost[s]\" of providers of health care services to Medicare beneficiaries, while § 1395x(v)(1)(A) empowers the Secretary to issue regulations setting forth the methods to be used in computing reasonable costs, which may include the establishment of appropriate cost …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"Gwaltney of Smithfield, Ltd. v. Chesapeake Bay Found.","cite":"484 U.S. 49","y":1987,"id":"1987/86-473","sc":1,"sum":"Section 505(a) of the Clean Water Act authorizes private citizens to commence a civil action for injunctive relief and/or the imposition of civil penalties in federal district court against any person \"alleged to be in violation\" of the conditions of a National Pollutant Discharge Elimination System (NPDES) permit. Between 1981 and 1984, petitioner repeatedly violated the conditions of its NPDES permit by exceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19"}},{"t":"case","label":"Johnson v. United States","cite":"529 U.S. 694","y":2000,"id":"1999/99-5153","sc":1,"op":1,"sum":"The Court held that 18 USC section 3583(h) is not retroactively applicable; however, its prior version, 18 USC section 3583(e)(3), authorizes a Federal District Court to impose additional term of supervised release after revocation of initial term and reimprisonment.","sumSrc":"Oyez","by":{"0":"28","1":"passim"}},{"t":"case","label":"Jones v. United States","cite":"527 U.S. 373","y":1999,"id":"1998/97-9361","sc":1,"sum":"The Court held that Jones was not entitled to an instruction as to the effect of jury deadlock. The Court held that the Eighth Amendment does not require such an instruction and the Court declined to exercise its supervisory powers to require such an instruction in every capital case.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"King v. Burwell, ___ U.S. ___","cite":"135 S. Ct. 2480","y":2015,"id":"2014/14-114","sc":1,"sum":"The Court determined that the plain language of the Affordable Care Act extended tax credits to federally-created exchanges as well as those the states created.","sumSrc":"Oyez","by":{"0":"17, 25"}},{"t":"case","label":"Kokkonen v. Guardian Life Ins. Co.","cite":"511 U.S. 375","y":1994,"id":"1993/93-263","sc":1,"sum":"A federal district court, possessing only that power authorized by Constitution and statute, lacks jurisdiction over a claim for breach of a contract, part of the consideration for which was dismissal of an earlier federal suit. No federal statute makes that connection (if it constitutionally could) the basis for federal-court jurisdiction over the contract dispute. Moreover, the doctrine of ancillary jurisdiction …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Landgraf v. U.S. Film Prods.","cite":"511 U.S. 244","y":1994,"id":"1993/92-757","sc":1,"sum":"Section 102 does not apply to a Title VII case that was pending on appeal when the 1991 Act was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Lynch v. Alworth-Stephens Co.","cite":"267 U.S. 364","y":1925,"id":"scdb/1924-237","sc":1,"by":{"0":"17"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25","1":"41"}},{"t":"case","label":"United States v. Cotton","cite":"535 U.S. 625","y":2002,"id":"2001/01-687","sc":1,"sum":"The Court held that the omission from a federal indictment of a fact that enhances the statutory maximum sentence does not justify a Court of Appeals' vacating the enhanced sentence, even though the defendant did not object in the trial court.","sumSrc":"Oyez","by":{"0":"32"}},{"t":"case","label":"United States v. Goins","cite":"516 F.3d 416","y":2008,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/516/416/","op":3,"by":{"0":"passim","1":"11","2":"7"}},{"t":"case","label":"United States v. Ide","cite":"624 F.3d 666","y":2010,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/624/666/","op":1,"by":{"0":"14, 26"}},{"t":"case","label":"United States v. Johnson","cite":"529 U.S. 53","y":2000,"id":"1999/98-1696","sc":1,"op":2,"sum":"The Court held that the length of a supervised release term cannot be reduced by reason of excess time served in prison.","sumSrc":"Oyez","by":{"0":"15, 19, 20, 23","1":"22, 23, 26","2":"2, 3, 8, 9"}},{"t":"case","label":"United States v. Johnson","cite":"581 F.3d 1310","court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/581/1310/","op":1,"by":{"0":"14"}},{"t":"case","label":"United States v. Madden","cite":"515 F.3d 601","court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/515/601/","by":{"0":"11"}},{"t":"case","label":"United States v. Marsh","cite":"829 F.3d 705","court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/829/705/","op":3,"sum":"Holding that pretrial detention does not apply to the language in §3624(e).","sumSrc":"brief:0","by":{"0":"14, 21"}},{"t":"case","label":"United States v. Menasche","cite":"348 U.S. 528","y":1955,"id":"scdb/1954-050","sc":1,"sum":"An alien who filed his declaration of intention to become an American citizen before the effective date of the Immigration and Nationality Act bf 1952, and who otherwise complied with the naturalization laws then in effect, has a \"status,\" \"condition\" or \"right in process 9 f acquisition\" preserved by § 405 (a), the general savings clause of the 1952 Act, even though his petition for naturalization was filed after …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"United States v. Molina-Gazca","cite":"571 F.3d 470","court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/571/470/","op":1,"by":{"0":"14"}},{"t":"case","label":"United States v. Mont","cite":"723 Fed. Appx. 325","court":"6th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./723/325/","op":8,"by":{"0":"12, 14, 23"}},{"t":"case","label":"United States v. Neville","cite":"985 F.2d 982","court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/985/982/","by":{"0":"30"}},{"t":"case","label":"United States v. Wilson","cite":"503 U.S. 329","y":1992,"id":"1991/90-1745","sc":1,"sum":"It is the Attorney General who computes the amount of the § 3585(b) credit after the defendant has begun to serve his sentence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"16","1":"30"}},{"t":"case","label":"Williams v. Taylor","cite":"529 U.S. 362","y":2000,"id":"1999/98-8384","sc":1,"sum":"In a judgment announced by Justice John Paul Stevens, the Court, with different majorities of Justices for each holding, held that Williams had been deprived of the constitutional right to the effective assistance of counsel and that the Virginia Supreme Court's refusal to set aside the Williams death sentence was a decision that was contrary to or involved an unreasonable application of clearly established federal law, as determined by the Court.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Yates v. United States, ___ U.S. ___","cite":"135 S. Ct. 1074","y":2015,"id":"2014/13-7451","sc":1,"sum":"The Court ruled that a “tangible item” as defined by Section 1519 of the Sarbanes-Oxley Act is one used to record or preserve information.","sumSrc":"Oyez","by":{"0":"27"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","stext":{"head":"§1. Words denoting number, gender, and so forth","paras":[[0,"In determining the meaning of any Act of Congress, unless the context indicates otherwise—"],[1,"words importing the singular include and apply to several persons, parties, or things;"],[1,"words importing the plural include the singular;"],[1,"words importing the masculine gender include the feminine as well;"],[1,"words used in the present tense include the future as well as the present;"],[1,"the words \"insane\" and \"insane person\" shall include every idiot, insane person, and person non compos mentis;"],[1,"the words \"person\" and \"whoever\" include corporations, companies, associations, firms, partnerships, societies, and joint stock companies, as well as individuals;"],[1,"\"officer\" includes any person authorized by law to perform the duties of the office;"],[1,"\"signature\" or \"subscription\" includes a mark when the person making the same intended it as such;"],[1,"\"oath\" includes affirmation, and \"sworn\" includes affirmed;"],[1,"\"writing\" includes printing and typewriting and reproductions of visual symbols by photographing, multigraphing, mimeographing, manifolding, or otherwise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/1?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§1. Words denoting number, gender, and so forth","tname":"General Provisions","by":{"0":"21","1":"32"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(1)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"0":"7","1":"3"}},{"t":"usc","label":"18 U.S.C. § 3041","url":"https://www.law.cornell.edu/uscode/text/18/3041","stext":{"head":"§3041. Power of courts and magistrates","paras":[[0,"For any offense against the United States, the offender may, by any justice or judge of the United States, or by any United States magistrate judge, or by any chancellor, judge of a supreme or superior court, chief or first judge of the common pleas, mayor of a city, justice of the peace, or other magistrate, of any state where the offender may be found, and at the expense of the United States, be arrested and imprisoned or released as provided in chapter 207 of this title, as the case may be, for trial before such court of the United States as by law has cognizance of the offense. Copies of the process shall be returned as speedily as may be into the office of the clerk of such court, together with the recognizances of the witnesses for their appearances to testify in the case."],[0,"A United States judge or magistrate judge shall proceed under this section according to rules promulgated by the Supreme Court of the United States. Any state judge or magistrate acting hereunder may proceed according to the usual mode of procedure of his state but his acts and orders shall have no effect beyond determining, pursuant to the provisions of section 3142 of this title, whether to detain or conditionally release the prisoner prior to trial or to discharge him from arrest."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3041?type=usc&year=mostrecent&link-type=html"},"head":"§3041. Power of courts and magistrates","tname":"Crimes and Criminal Procedure","by":{"0":"25, 26","1":"17","2":"11, 12"}},{"t":"usc","label":"18 U.S.C. § 3231","url":"https://www.law.cornell.edu/uscode/text/18/3231","by":{"0":"30"}},{"t":"usc","label":"18 U.S.C. § 3565","url":"https://www.law.cornell.edu/uscode/text/18/3565","subs":["(c)"],"by":{"0":"31, 33"}},{"t":"usc","label":"18 U.S.C. § 3583","url":"https://www.law.cornell.edu/uscode/text/18/3583","subs":["(a)","(i)","(d)","(e)","(e)(3)","(g)"],"stext":{"head":"§3583. Inclusion of a term of supervised release after imprisonment","paras":[[0,"(a) In General.—The court, in imposing a sentence to a term of imprisonment for a felony or a misdemeanor, may include as a part of the sentence a requirement that the defendant be placed on a term of supervised release after imprisonment, except that the court shall include as a part of the sentence a requirement that the defendant be placed on a term of supervised release if such a term is required by statute or if the defendant has been convicted for the first time of a domestic violence crime as defined in section 3561(b)."],[0,"(b) Authorized Terms of Supervised Release.—Except as otherwise provided, the authorized terms of supervised release are—"],[1,"(1) for a Class A or Class B felony, not more than five years;"],[1,"(2) for a Class C or Class D felony, not more than three years; and"],[1,"(3) for a Class E felony, or for a misdemeanor (other than a petty offense), not more than one year."],[0,"(c) Factors To Be Considered in Including a Term of Supervised Release.—The court, in determining whether to include a term of supervised release, and, if a term of supervised release is to be included, in determining the length of the term and the conditions of supervised release, shall consider the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)."],[0,"(d) Conditions of Supervised Release.—The court shall order, as an explicit condition of supervised release, that the defendant not commit another Federal, State, or local crime during the term of supervision, that the defendant make restitution in accordance with sections 3663 and 3663A, or any other statute authorizing a sentence of restitution, and that the defendant not unlawfully possess a controlled substance. The court shall order as an explicit condition of supervised release for a defendant convicted for the first time of a domestic violence crime as defined in section 3561(b) that the defendant attend a public, private, or private nonprofit offender rehabilitation program that has been approved by the court, in consultation with a State Coalition Against Domestic Violence or other appropriate experts, if an approved program is readily available within a 50-mile radius of the legal residence of the defendant. The court shall order, as an explicit condition of supervised release for a person required to register under the Sex Offender Registration and Notification Act, that the person comply with the requirements of that Act. The court shall order, as an explicit condition of supervised release, that the defendant cooperate in the collection of a DNA sample from the defendant, if the collection of such a sample is authorized pursuant to section 3 of the DNA Analysis Backlog Elimination Act of 2000. The court shall also order, as an explicit condition of supervised release, that the defendant refrain from any unlawful use of a controlled substance and submit to a drug test within 15 days of release on supervised release and at least 2 periodic drug tests thereafter (as determined by the court) for use of a controlled substance. The condition stated in the preceding sentence may be ameliorated or suspended by the court as provided in section 3563(a)(4).1 The results of a drug test administered in accordance with the preceding subsection shall be subject to confirmation only if the results are positive, the defendant is subject to possible imprisonment for such failure, and either the defendant denies the accuracy of such test or there is some other reason to question the results of the test. A drug test confirmation shall be a urine drug test confirmed using gas chromatography/mass spectrometry techniques or such test as the Director of the Administrative Office of the United States Courts after consultation with the Secretary of Health and Human Services may determine to be of equivalent accuracy. The court shall consider whether the availability of appropriate substance abuse treatment programs, or an individual's current or past participation in such programs, warrants an exception in accordance with United States Sentencing Commission guidelines from the rule of section 3583(g) when considering any action against a defendant who fails a drug test. The court may order, as a further condition of supervised release, to the extent that such condition—"],[1,"(1) is reasonably related to the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), and (a)(2)(D);"],[1,"(2) involves no greater deprivation of liberty than is reasonably necessary for the purposes set forth in section 3553(a)(2)(B), (a)(2)(C), and (a)(2)(D); and"],[1,"(3) is consistent with any pertinent policy statements issued by the Sentencing Commission pursuant to 28 U.S.C. 994(a);"],[0,"any condition set forth as a discretionary condition of probation in section 3563(b) and any other condition it considers to be appropriate, provided, however that a condition set forth in subsection 3563(b)(10) shall be imposed only for a violation of a condition of supervised release in accordance with section 3583(e)(2) and only when facilities are available. If an alien defendant is subject to deportation, the court may provide, as a condition of supervised release, that he be deported and remain outside the United States, and may order that he be delivered to a duly authorized immigration official for such deportation. The court may order, as an explicit condition of supervised release for a person who is a felon and required to register under the Sex Offender Registration and Notification Act, that the person submit his person, and any property, house, residence, vehicle, papers, computer, other electronic communications or data storage devices or media, and effects to search at any time, with or without a warrant, by any law enforcement or probation officer with reasonable suspicion concerning a violation of a condition of supervised release or unlawful conduct by the person, and by any probation officer in the lawful discharge of the officer's supervision functions."],[0,"(e) Modification of Conditions or Revocation.—The court may, after considering the factors set forth in section 3553(a)(1), (a)(2)(B), (a)(2)(C), (a)(2)(D), (a)(4), (a)(5), (a)(6), and (a)(7)—"],[1,"(1) terminate a term of supervised release and discharge the defendant released at any time after the expiration of one year of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation, if it is satisfied that such action is warranted by the conduct of the defendant released and the interest of justice;"],[1,"(2) extend a term of supervised release if less than the maximum authorized term was previously imposed, and may modify, reduce, or enlarge the conditions of supervised release, at any time prior to the expiration or termination of the term of supervised release, pursuant to the provisions of the Federal Rules of Criminal Procedure relating to the modification of probation and the provisions applicable to the initial setting of the terms and conditions of post-release supervision;"],[1,"(3) revoke a term of supervised release, and require the defendant to serve in prison all or part of the term of supervised release authorized by statute for the offense that resulted in such term of supervised release without credit for time previously served on postrelease supervision, if the court, pursuant to the Federal Rules of Criminal Procedure applicable to revocation of probation or supervised release, finds by a preponderance of the evidence that the defendant violated a condition of supervised release, except that a defendant whose term is revoked under this paragraph may not be required to serve on any such revocation more than 5 years in prison if the offense that resulted in the term of supervised release is a class A felony, more than 3 years in prison if such offense is a class B felony, more than 2 years in prison if such offense is a class C or D felony, or more than one year in any other case; or"],[1,"(4) order the defendant to remain at his place of residence during nonworking hours and, if the court so directs, to have compliance monitored by telephone or electronic signaling devices, except that an order under this paragraph may be imposed only as an alternative to incarceration."],[0,"(f) Written Statement of Conditions.—The court shall direct that the probation officer provide the defendant with a written statement that sets forth all the conditions to which the term of supervised release is subject, and that is sufficiently clear and specific to serve as a guide for the defendant's conduct and for such supervision as is required."],[0,"(g) Mandatory Revocation for Possession of Controlled Substance or Firearm or for Refusal To Comply With Drug Testing.—If the defendant—"],[1,"(1) possesses a controlled substance in violation of the condition set forth in subsection (d);"],[1,"(2) possesses a firearm, as such term is defined in section 921 of this title, in violation of Federal law, or otherwise violates a condition of supervised release prohibiting the defendant from possessing a firearm;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3583?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§3583. Inclusion of a term of supervised release after imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"1, 31, 5, passim","1":"26, 4, 24, 29, 4, 10, 11, 36, 37","2":"17, 1, 19, 20, 22, 23"}},{"t":"usc","label":"18 U.S.C. § 3585","url":"https://www.law.cornell.edu/uscode/text/18/3585","subs":["(a)","(b)","(b)(1)","(b)(2)"],"stext":{"head":"§3585. Calculation of a term of imprisonment","paras":[[0,"(a) Commencement of Sentence.—A sentence to a term of imprisonment commences on the date the defendant is received in custody awaiting transportation to, or arrives voluntarily to commence service of sentence at, the official detention facility at which the sentence is to be served."],[0,"(b) Credit for Prior Custody.—A defendant shall be given credit toward the service of a term of imprisonment for any time he has spent in official detention prior to the date the sentence commences—"],[1,"(1) as a result of the offense for which the sentence was imposed; or"],[1,"(2) as a result of any other charge for which the defendant was arrested after the commission of the offense for which the sentence was imposed;"],[0,"that has not been credited against another sentence."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3585?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3585. Calculation of a term of imprisonment","tname":"Crimes and Criminal Procedure","by":{"0":"28, 28, 28","1":"30, 21, 30, 30","2":"7, 15, 16, 24, 15, 15, 16"}},{"t":"usc","label":"18 U.S.C. § 3624","url":"https://www.law.cornell.edu/uscode/text/18/3624","subs":["(e)","(b)"],"stext":{"head":"§3624. Release of a prisoner","paras":[[0,"(a) Date of Release.—A prisoner shall be released by the Bureau of Prisons on the date of the expiration of the prisoner's term of imprisonment, less any time credited toward the service of the prisoner's sentence as provided in subsection (b). If the date for a prisoner's release falls on a Saturday, a Sunday, or a legal holiday at the place of confinement, the prisoner may be released by the Bureau on the last preceding weekday."],[0,"(b) Credit Toward Service of Sentence for Satisfactory Behavior.—(1) Subject to paragraph (2), a prisoner who is serving a term of imprisonment of more than 1 year 1 other than a term of imprisonment for the duration of the prisoner's life, may receive credit toward the service of the prisoner's sentence of up to 54 days for each year of the prisoner's sentence imposed by the court, subject to determination by the Bureau of Prisons that, during that year, the prisoner has displayed exemplary compliance with institutional disciplinary regulations. Subject to paragraph (2), if the Bureau determines that, during that year, the prisoner has not satisfactorily complied with such institutional regulations, the prisoner shall receive no such credit toward service of the prisoner's sentence or shall receive such lesser credit as the Bureau determines to be appropriate. In awarding credit under this section, the Bureau shall consider whether the prisoner, during the relevant period, has earned, or is making satisfactory progress toward earning, a high school diploma or an equivalent degree. Credit that has not been earned may not later be granted. Subject to paragraph (2), credit for the last year of a term of imprisonment shall be credited on the first day of the last year of the term of imprisonment."],[0,"(2) Notwithstanding any other law, credit awarded under this subsection after the date of enactment of the Prison Litigation Reform Act shall vest on the date the prisoner is released from custody."],[0,"(3) The Attorney General shall ensure that the Bureau of Prisons has in effect an optional General Educational Development program for inmates who have not earned a high school diploma or its equivalent."],[0,"(4) Exemptions to the General Educational Development requirement may be made as deemed appropriate by the Director of the Federal Bureau of Prisons."],[0,"(c) Prerelease Custody.—"],[1,"(1) In general.—The Director of the Bureau of Prisons shall, to the extent practicable, ensure that a prisoner serving a term of imprisonment spends a portion of the final months of that term (not to exceed 12 months), under conditions that will afford that prisoner a reasonable opportunity to adjust to and prepare for the reentry of that prisoner into the community. Such conditions may include a community correctional facility."],[1,"(2) Home confinement authority.—The authority under this subsection may be used to place a prisoner in home confinement for the shorter of 10 percent of the term of imprisonment of that prisoner or 6 months. The Bureau of Prisons shall, to the extent practicable, place prisoners with lower risk levels and lower needs on home confinement for the maximum amount of time permitted under this paragraph."],[1,"(3) Assistance.—The United States Probation System shall, to the extent practicable, offer assistance to a prisoner during prerelease custody under this subsection."],[1,"(4) No limitations.—Nothing in this subsection shall be construed to limit or restrict the authority of the Director of the Bureau of Prisons under section 3621."],[1,"(5) Reporting.—Not later than 1 year after the date of the enactment of the Second Chance Act of 2007 (and every year thereafter), the Director of the Bureau of Prisons shall transmit to the Committee on the Judiciary of the Senate and the Committee on the Judiciary of the House of Representatives a report describing the Bureau's utilization of community corrections facilities. Each report under this paragraph shall set forth the number and percentage of Federal prisoners placed in community corrections facilities during the preceding year, the average length of such placements, trends in such utilization, the reasons some prisoners are not placed in community corrections facilities, and number of prisoners not being placed in community corrections facilities for each reason set forth, and any other information that may be useful to the committees in determining if the Bureau is utilizing community corrections facilities in an effective manner."],[1,"(6) Issuance of regulations.—The Director of the Bureau of Prisons shall issue regulations pursuant to this subsection not later than 90 days after the date of the enactment of the Second Chance Reauthorization Act of 2018, which shall ensure that placement in a community correctional facility by the Bureau of Prisons is—"],[2,"(A) conducted in a manner consistent with section 3621(b) of this title;"],[2,"(B) determined on an individual basis; and"],[2,"(C) of sufficient duration to provide the greatest likelihood of successful reintegration into the community."],[0,"(d) Allotment of Clothing, Funds, and Transportation.—Upon the release of a prisoner on the expiration of the prisoner's term of imprisonment, the Bureau of Prisons shall furnish the prisoner with—"],[1,"(1) suitable clothing;"],[1,"(2) an amount of money, not more than $500, determined by the Director to be consistent with the needs of the offender and the public interest, unless the Director determines that the financial position of the offender is such that no sum should be furnished; and"],[1,"(3) transportation to the place of the prisoner's conviction, to the prisoner's bona fide residence within the United States, or to such other place within the United States as may be authorized by the Director."],[0,"(e) Supervision After Release.—A prisoner whose sentence includes a term of supervised release after imprisonment shall be released by the Bureau of Prisons to the supervision of a probation officer who shall, during the term imposed, supervise the person released to the degree warranted by the conditions specified by the sentencing court. The term of supervised release commences on the day the person is released from imprisonment and runs concurrently with any Federal, State, or local term of probation or supervised release or parole for another offense to which the person is subject or becomes subject during the term of supervised release. A term of supervised release does not run during any period in which the person is imprisoned in connection with a conviction for a Federal, State, or local crime unless the imprisonment is for a period of less than 30 consecutive days. Upon the release of a prisoner by the Bureau of Prisons to supervised release, the Bureau of Prisons shall notify such prisoner, verbally and in writing, of the requirement that the prisoner adhere to an installment schedule, not to exceed 2 years except in special circumstances, to pay for any fine imposed for the offense committed by such prisoner, and of the consequences of failure to pay such fines under sections 3611 through 3614 of this title."],[0,"(f) Mandatory Functional Literacy Requirement.—"],[1,"(1) The Attorney General shall direct the Bureau of Prisons to have in effect a mandatory functional literacy program for all mentally capable inmates who are not functionally literate in each Federal correctional institution within 6 months from the date of the enactment of this Act."],[1,"(2) Each mandatory functional literacy program shall include a requirement that each inmate participate in such program for a mandatory period sufficient to provide the inmate with an adequate opportunity to achieve functional literacy, and appropriate incentives which lead to successful completion of such programs shall be developed and implemented."],[1,"(3) As used in this section, the term \"functional literacy\" means—"],[2,"(A) an eighth grade equivalence in reading and mathematics on a nationally recognized standardized test;"],[2,"(B) functional competency or literacy on a nationally recognized criterion-referenced test; or"],[2,"(C) a combination of subparagraphs (A) and (B)."],[1,"(4) Non-English speaking inmates shall be required to participate in an English-As-A-Second-Language program until they function at the equivalence of the eighth grade on a nationally recognized educational achievement test."],[1,"(5) The Chief Executive Officer of each institution shall have authority to grant waivers for good cause as determined and documented on an individual basis."],[0,"(g) Prerelease Custody or Supervised Release for Risk and Needs Assessment System Participants.—"],[1,"(1) Eligible prisoners.—This subsection applies in the case of a prisoner (as such term is defined in section 3635) who—"],[2,"(A) has earned time credits under the risk and needs assessment system developed under subchapter D (referred to in this subsection as the \"System\") in an amount that is equal to the remainder of the prisoner's imposed term of imprisonment;"],[2,"(B) has shown through the periodic risk reassessments a demonstrated recidivism risk reduction or has maintained a minimum or low recidivism risk, during the prisoner's term of imprisonment;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3624?type=usc&year=mostrecent&link-type=html"},"op":3,"ar":1,"head":"§3624. Release of a prisoner","tname":"Crimes and Criminal Procedure","by":{"0":"2, 3, 5, 13, 23, passim","1":"passim, 22","2":"6, 7, 10, 9, 16, 24, passim"}},{"t":"usc","label":"18 U.S.C. § 3626","url":"https://www.law.cornell.edu/uscode/text/18/3626","subs":["(g)","(g)(5)"],"stext":{"head":"§3626. Appropriate remedies with respect to prison conditions","paras":[[0,"(a) Requirements for Relief.—"],[1,"(1) Prospective relief.—(A) Prospective relief in any civil action with respect to prison conditions shall extend no further than necessary to correct the violation of the Federal right of a particular plaintiff or plaintiffs. The court shall not grant or approve any prospective relief unless the court finds that such relief is narrowly drawn, extends no further than necessary to correct the violation of the Federal right, and is the least intrusive means necessary to correct the violation of the Federal right. The court shall give substantial weight to any adverse impact on public safety or the operation of a criminal justice system caused by the relief."],[1,"(B) The court shall not order any prospective relief that requires or permits a government official to exceed his or her authority under State or local law or otherwise violates State or local law, unless—"],[2,"(i) Federal law requires such relief to be ordered in violation of State or local law;"],[2,"(ii) the relief is necessary to correct the violation of a Federal right; and"],[2,"(iii) no other relief will correct the violation of the Federal right."],[1,"(C) Nothing in this section shall be construed to authorize the courts, in exercising their remedial powers, to order the construction of prisons or the raising of taxes, or to repeal or detract from otherwise applicable limitations on the remedial powers of the courts."],[1,"(2) Preliminary injunctive relief.—In any civil action with respect to prison conditions, to the extent otherwise authorized by law, the court may enter a temporary restraining order or an order for preliminary injunctive relief. Preliminary injunctive relief must be narrowly drawn, extend no further than necessary to correct the harm the court finds requires preliminary relief, and be the least intrusive means necessary to correct that harm. The court shall give substantial weight to any adverse impact on public safety or the operation of a criminal justice system caused by the preliminary relief and shall respect the principles of comity set out in paragraph (1)(B) in tailoring any preliminary relief. Preliminary injunctive relief shall automatically expire on the date that is 90 days after its entry, unless the court makes the findings required under subsection (a)(1) for the entry of prospective relief and makes the order final before the expiration of the 90-day period."],[1,"(3) Prisoner release order.—(A) In any civil action with respect to prison conditions, no court shall enter a prisoner release order unless—"],[2,"(i) a court has previously entered an order for less intrusive relief that has failed to remedy the deprivation of the Federal right sought to be remedied through the prisoner release order; and"],[2,"(ii) the defendant has had a reasonable amount of time to comply with the previous court orders."],[1,"(B) In any civil action in Federal court with respect to prison conditions, a prisoner release order shall be entered only by a three-judge court in accordance with section 2284 of title 28, if the requirements of subparagraph (E) have been met."],[1,"(C) A party seeking a prisoner release order in Federal court shall file with any request for such relief, a request for a three-judge court and materials sufficient to demonstrate that the requirements of subparagraph (A) have been met."],[1,"(D) If the requirements under subparagraph (A) have been met, a Federal judge before whom a civil action with respect to prison conditions is pending who believes that a prison release order should be considered may sua sponte request the convening of a three-judge court to determine whether a prisoner release order should be entered."],[1,"(E) The three-judge court shall enter a prisoner release order only if the court finds by clear and convincing evidence that—"],[2,"(i) crowding is the primary cause of the violation of a Federal right; and"],[2,"(ii) no other relief will remedy the violation of the Federal right."],[1,"(F) Any State or local official including a legislator or unit of government whose jurisdiction or function includes the appropriation of funds for the construction, operation, or maintenance of prison facilities, or the prosecution or custody of persons who may be released from, or not admitted to, a prison as a result of a prisoner release order shall have standing to oppose the imposition or continuation in effect of such relief and to seek termination of such relief, and shall have the right to intervene in any proceeding relating to such relief."],[0,"(b) Termination of Relief.—"],[1,"(1) Termination of prospective relief.—(A) In any civil action with respect to prison conditions in which prospective relief is ordered, such relief shall be terminable upon the motion of any party or intervener—"],[2,"(i) 2 years after the date the court granted or approved the prospective relief;"],[2,"(ii) 1 year after the date the court has entered an order denying termination of prospective relief under this paragraph; or"],[2,"(iii) in the case of an order issued on or before the date of enactment of the Prison Litigation Reform Act, 2 years after such date of enactment."],[1,"(B) Nothing in this section shall prevent the parties from agreeing to terminate or modify relief before the relief is terminated under subparagraph (A)."],[1,"(2) Immediate termination of prospective relief.—In any civil action with respect to prison conditions, a defendant or intervener shall be entitled to the immediate termination of any prospective relief if the relief was approved or granted in the absence of a finding by the court that the relief is narrowly drawn, extends no further than necessary to correct the violation of the Federal right, and is the least intrusive means necessary to correct the violation of the Federal right."],[1,"(3) Limitation.—Prospective relief shall not terminate if the court makes written findings based on the record that prospective relief remains necessary to correct a current and ongoing violation of the Federal right, extends no further than necessary to correct the violation of the Federal right, and that the prospective relief is narrowly drawn and the least intrusive means to correct the violation."],[1,"(4) Termination or modification of relief.—Nothing in this section shall prevent any party or intervener from seeking modification or termination before the relief is terminable under paragraph (1) or (2), to the extent that modification or termination would otherwise be legally permissible."],[0,"(c) Settlements.—"],[1,"(1) Consent decrees.—In any civil action with respect to prison conditions, the court shall not enter or approve a consent decree unless it complies with the limitations on relief set forth in subsection (a)."],[1,"(2) Private settlement agreements.—(A) Nothing in this section shall preclude parties from entering into a private settlement agreement that does not comply with the limitations on relief set forth in subsection (a), if the terms of that agreement are not subject to court enforcement other than the reinstatement of the civil proceeding that the agreement settled."],[1,"(B) Nothing in this section shall preclude any party claiming that a private settlement agreement has been breached from seeking in State court any remedy available under State law."],[0,"(d) State Law Remedies.—The limitations on remedies in this section shall not apply to relief entered by a State court based solely upon claims arising under State law."],[0,"(e) Procedure for Motions Affecting Prospective Relief.—"],[1,"(1) Generally.—The court shall promptly rule on any motion to modify or terminate prospective relief in a civil action with respect to prison conditions. Mandamus shall lie to remedy any failure to issue a prompt ruling on such a motion."],[1,"(2) Automatic stay.—Any motion to modify or terminate prospective relief made under subsection (b) shall operate as a stay during the period—"],[2,"(A)(i) beginning on the 30th day after such motion is filed, in the case of a motion made under paragraph (1) or (2) of subsection (b); or"],[2,"(ii) beginning on the 180th day after such motion is filed, in the case of a motion made under any other law; and"],[2,"(B) ending on the date the court enters a final order ruling on the motion."],[1,"(3) Postponement of automatic stay.—The court may postpone the effective date of an automatic stay specified in subsection (e)(2)(A) for not more than 60 days for good cause. No postponement shall be permissible because of general congestion of the court's calendar."],[1,"(4) Order blocking the automatic stay.—Any order staying, suspending, delaying, or barring the operation of the automatic stay described in paragraph (2) (other than an order to postpone the effective date of the automatic stay under paragraph (3)) shall be treated as an order refusing to dissolve or modify an injunction and shall be appealable pursuant to section 1292(a)(1) of title 28, United States Code, regardless of how the order is styled or whether the order is termed a preliminary or a final ruling."],[0,"(f) Special Masters.—"],[1,"(1) In general.—(A) In any civil action in a Federal court with respect to prison conditions, the court may appoint a special master who shall be disinterested and objective and who will give due regard to the public safety, to conduct hearings on the record and prepare proposed findings of fact."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3626?type=usc&year=mostrecent&link-type=html"},"head":"§3626. Appropriate remedies with respect to prison conditions","tname":"Crimes and Criminal Procedure","by":{"0":"25, 25","1":"17"}},{"t":"usc","label":"21 U.S.C. § 841","url":"https://www.law.cornell.edu/uscode/text/21/841","subs":["(a)(1)","(b)(1)(A)"],"stext":{"head":"§841. Prohibited acts A","paras":[[0,"(a) Unlawful acts"],[0,"Except as authorized by this subchapter, it shall be unlawful for any person knowingly or intentionally—"],[1,"(1) to manufacture, distribute, or dispense, or possess with intent to manufacture, distribute, or dispense, a controlled substance; or"],[1,"(2) to create, distribute, or dispense, or possess with intent to distribute or dispense, a counterfeit substance."],[0,"(b) Penalties"],[0,"Except as otherwise provided in section 849, 859, 860, or 861 of this title, any person who violates subsection (a) of this section shall be sentenced as follows:"],[0,"(1)(A) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 1 kilogram or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 5 kilograms or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 280 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 100 grams or more of phencyclidine (PCP) or 1 kilogram or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 10 grams or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 400 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 100 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 1000 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 1,000 or more marihuana plants regardless of weight; or"],[1,"(viii) 50 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 500 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 10 years or more than life and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $10,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment of not less than 15 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $20,000,000 if the defendant is an individual or $75,000,000 if the defendant is other than an individual, or both. If any person commits a violation of this subparagraph or of section 849, 859, 860, or 861 of this title after 2 or more prior convictions for a serious drug felony or serious violent felony have become final, such person shall be sentenced to a term of imprisonment of not less than 25 years and fined in accordance with the preceding sentence. Notwithstanding section 3583 of title 18, any sentence under this subparagraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 5 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 10 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(B) In the case of a violation of subsection (a) of this section involving—"],[1,"(i) 100 grams or more of a mixture or substance containing a detectable amount of heroin;"],[1,"(ii) 500 grams or more of a mixture or substance containing a detectable amount of—"],[2,"(I) coca leaves, except coca leaves and extracts of coca leaves from which cocaine, ecgonine, and derivatives of ecgonine or their salts have been removed;"],[2,"(II) cocaine, its salts, optical and geometric isomers, and salts of isomers;"],[2,"(III) ecgonine, its derivatives, their salts, isomers, and salts of isomers; or"],[2,"(IV) any compound, mixture, or preparation which contains any quantity of any of the substances referred to in subclauses (I) through (III);"],[1,"(iii) 28 grams or more of a mixture or substance described in clause (ii) which contains cocaine base;"],[1,"(iv) 10 grams or more of phencyclidine (PCP) or 100 grams or more of a mixture or substance containing a detectable amount of phencyclidine (PCP);"],[1,"(v) 1 gram or more of a mixture or substance containing a detectable amount of lysergic acid diethylamide (LSD);"],[1,"(vi) 40 grams or more of a mixture or substance containing a detectable amount of N-phenyl-N- [ 1- ( 2-phenylethyl ) -4-piperidinyl ] propanamide or 10 grams or more of a mixture or substance containing a detectable amount of any analogue of N-phenyl-N-[1-(2-phenylethyl)-4-piperidinyl] propanamide;"],[1,"(vii) 100 kilograms or more of a mixture or substance containing a detectable amount of marihuana, or 100 or more marihuana plants regardless of weight; or"],[1,"(viii) 5 grams or more of methamphetamine, its salts, isomers, and salts of its isomers or 50 grams or more of a mixture or substance containing a detectable amount of methamphetamine, its salts, isomers, or salts of its isomers;"],[0,"such person shall be sentenced to a term of imprisonment which may not be less than 5 years and not more than 40 years and if death or serious bodily injury results from the use of such substance shall be not less than 20 years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $5,000,000 if the defendant is an individual or $25,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a serious drug felony or serious violent felony has become final, such person shall be sentenced to a term of imprisonment which may not be less than 10 years and not more than life imprisonment and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $8,000,000 if the defendant is an individual or $50,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposed under this subparagraph shall, in the absence of such a prior conviction, include a term of supervised release of at least 4 years in addition to such term of imprisonment and shall, if there was such a prior conviction, include a term of supervised release of at least 8 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under this subparagraph. No person sentenced under this subparagraph shall be eligible for parole during the term of imprisonment imposed therein."],[0,"(C) In the case of a controlled substance in schedule I or II, gamma hydroxybutyric acid (including when scheduled as an approved drug product for purposes of section 3(a)(1)(B) of the Hillory J. Farias and Samantha Reid Date-Rape Drug Prohibition Act of 2000), or 1 gram of flunitrazepam, except as provided in subparagraphs (A), (B), and (D), such person shall be sentenced to a term of imprisonment of not more than 20 years and if death or serious bodily injury results from the use of such substance shall be sentenced to a term of imprisonment of not less than twenty years or more than life, a fine not to exceed the greater of that authorized in accordance with the provisions of title 18 or $1,000,000 if the defendant is an individual or $5,000,000 if the defendant is other than an individual, or both. If any person commits such a violation after a prior conviction for a felony drug offense has become final, such person shall be sentenced to a term of imprisonment of not more than 30 years and if death or serious bodily injury results from the use of such substance shall be sentenced to life imprisonment, a fine not to exceed the greater of twice that authorized in accordance with the provisions of title 18 or $2,000,000 if the defendant is an individual or $10,000,000 if the defendant is other than an individual, or both. Notwithstanding section 3583 of title 18, any sentence imposing a term of imprisonment under this paragraph shall, in the absence of such a prior conviction, impose a term of supervised release of at least 3 years in addition to such term of imprisonment and shall, if there was such a prior conviction, impose a term of supervised release of at least 6 years in addition to such term of imprisonment. Notwithstanding any other provision of law, the court shall not place on probation or suspend the sentence of any person sentenced under the provisions of this subparagraph which provide for a mandatory term of imprisonment if death or serious bodily injury results, nor shall a person so sentenced be eligible for parole during the term of such a sentence."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/841?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§841. Prohibited acts A","tname":"Food and Drugs","by":{"0":"7, 7","1":"2, 3, 2, 3"}},{"t":"usc","label":"21 U.S.C. § 846","url":"https://www.law.cornell.edu/uscode/text/21/846","stext":{"head":"§846. Attempt and conspiracy","paras":[[0,"Any person who attempts or conspires to commit any offense defined in this subchapter shall be subject to the same penalties as those prescribed for the offense, the commission of which was the object of the attempt or conspiracy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/21/846?type=usc&year=mostrecent&link-type=html"},"head":"§846. Attempt and conspiracy","tname":"Food and Drugs","by":{"0":"7","1":"2, 3"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/1976","by":{"0":"4, 5, 4, 5, 24, 25","1":"20, 33, 3, 21"}},{"t":"law","label":"Pub. L. No. 103-322","url":"https://www.govinfo.gov/link/statute/108/1796","by":{"0":"6, 6, 31"}},{"t":"case","label":"Abbott v. United States","cite":"562 U.S. 8","y":2010,"id":"2010/09-479","sc":1,"sum":"The Court held that a defendant who receives a mandatory minimum sentence for using or carrying a firearm in furtherance of a drug trafficking crime can serve that sentence consecutively with any other term of imprisonment.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Bell v. Wolfish","cite":"441 U.S. 520","y":1979,"id":"1978/77-1829","sc":1,"sum":"The Court found that that the conditions of confinement did not infringe upon a pretrial detainee's rights. Justice Rehnquist's opinion argued that the issue of prison management is ripe with \"judgment calls\" which rest outside the jurisdiction of the judiciary.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Betterman v. Montana","cite":"136 S. Ct. 1609","y":2016,"id":"2015/14-1457","sc":1,"sum":"The Court determined that the Sixth Amendment’s guarantee of a speedy trial does not extend past a guilty verdict or guilty plea.","sumSrc":"Oyez","by":{"1":"39, 40"}},{"t":"case","label":"Boykin v. Alabama","cite":"395 U.S. 238","y":1969,"id":"1968/642","sc":1,"sum":"The Court held that a guilty plea is a confession, and the admissibility of a confession is contingent on the confirmation that it was made voluntarily. The waiver of several constitutional rights is involved in a guilty plea. A defendant’s silence is insufficient to show that he understood these rights and chose to waive them.","sumSrc":"Oyez","by":{"1":"39"}},{"t":"case","label":"Burrage v. United States","cite":"571 U.S. 204","y":2014,"id":"2013/12-7515","sc":1,"sum":"The Court held that, under 21 U.S.C. § 841(b) of the statute regarding drug-related deaths, an individual convicted of the death of another through the sale of drugs cannot be convicted of drug-induced homicide if multiple drugs are present in the deceased's system.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Caraco Pharm. Labs., Ltd. v. Novo Nordisk A/S","cite":"566 U.S. 399","y":2012,"id":"2011/10-844","sc":1,"sum":"The Court held that counterclaims that challenge unpatented uses of generic drugs, even if other approved uses are still under patent, are allowable under the Hatch-Waxman Act.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Deck v. Missouri","cite":"544 U.S. 622","y":2005,"id":"2004/04-5293","sc":1,"sum":"Justice Stephen Breyer delivered the Court's 7-2 holding that the Constitution forbids the use of visible shackles during both a capital trial's guilt and penalty phases, unless such shackling is justified by an essential state interest specific to the defendant on trial (such as courtroom security).","sumSrc":"Oyez","by":{"1":"40"}},{"t":"case","label":"Dickerson v. New Banner Inst., Inc.","cite":"460 U.S. 103","y":1983,"id":"1982/81-1180","sc":1,"sum":"The firearms disabilities imposed by §§ 922(g)(1) and (h)(1) apply to Kennison and were not removed by the expunction of the record of his guilty plea to the concealed weapon charge.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"41"}},{"t":"case","label":"Libretti v. United States","cite":"516 U.S. 29","y":1995,"id":"1995/94-7427","sc":1,"sum":"During petitioner Libretti's trial on federal drug and related charges, he entered into a plea agreement with the Government, whereby, among other things, he pleaded guilty to engaging in a continuing criminal enterprise under 21 U. S. C. §848; agreed to surrender numerous items of his property to the Government under § 853, which provides for criminal forfeiture of drug-tainted property; and waived his …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"39"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"op":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"1":"19, 21","2":"8, 9"}},{"t":"case","label":"McDonald v. Board of Election Comm’rs of Chi.","cite":"394 U.S. 802","y":1969,"id":"1968/68","sc":1,"sum":"Illinois' failure to provide absentee ballots for appellants does not violate the Equal Protection Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"McGinnis v. Royster","cite":"410 U.S. 263","y":1973,"id":"1972/71-718","sc":1,"sum":"Under the New York scheme good-time credit takes into account a prisoner's performance under the program of rehabilitation that is fostered under the state prison system, but not in the county jails, which serve primarily as detention centers. Since the jails have no significant rehabilitation program, a rational basis exists for declining to give good-time credit for the pretrial jail-detention period; and the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18"}},{"t":"case","label":"Merrill Lynch, Pierce, Fenner & Smith Inc. v. Dabit","cite":"547 U.S. 71","y":2006,"id":"2005/04-1371","sc":1,"op":1,"sum":"Interpreting “in connection with the purchase or sale” broadly in the context of §10(b) of the Securities Exchange Act of 1934, 15 U. S. C. §78j(b).","sumSrc":"opinion","by":{"1":"19","2":"4"}},{"t":"case","label":"Reno v. Koray","cite":"515 U.S. 50","y":1995,"id":"1994/94-790","sc":1,"sum":"The time respondent spent at the treatment center while \"released\" on bail was not \"official detention\" within the meaning of §3585(b).","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"30, 40"}},{"t":"case","label":"Spina v. Department of Homeland Sec.","cite":"470 F.3d 116","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/470/116/","by":{"1":"39"}},{"t":"case","label":"United States v. American Union Transp., Inc.","cite":"327 U.S. 437","y":1946,"id":"scdb/1945-068","sc":1,"op":1,"sum":"Describing the phrase “in connection with” in the Shipping Act, 1916, 39 Stat. 728, as “broad and general”.","sumSrc":"opinion","by":{"1":"19","2":"4"}},{"t":"case","label":"United States v. Loney","cite":"219 F.3d 281","y":2000,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/219/281/","sum":"Observing that dictionaries and usage experts give “expansive” scope to the phrase “ ‘in connection with’ ” as “express[ing] some relationship or association, one that can be satisfied in a number of ways”.","sumSrc":"brief:1","by":{"1":"19","2":"5"}},{"t":"case","label":"United States v. Thompson","cite":"32 F.3d 1","y":1994,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/32/1/","by":{"1":"19","2":"5"}},{"t":"case","label":"United States v. Trainor","cite":"376 F.3d 1325","y":2004,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/376/1325/","by":{"1":"34","2":"22, 23"}},{"t":"case","label":"Zerbst v. Kidwell","cite":"304 U.S. 359","y":1938,"id":"scdb/1937-051","sc":1,"sum":"A prisoner sentenced to a federal penal institution for an offense committed while he was on parole from such an institution may be required by the Parole Board to serve the unexpired portiou of his first sentence after the expiration of his second sentence. P. 363. 92 F. 2d 756, reversed. Together with No. 783, Zerbst, Warden, v. Smith; No. 784, Same v. Collins; No. 785, Same v. Owens; No. 786, Same v. Peel; No. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 3142","url":"https://www.law.cornell.edu/uscode/text/18/3142","subs":["(b)"],"by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 3143","url":"https://www.law.cornell.edu/uscode/text/18/3143","subs":["(a)"],"by":{"1":"40"}},{"t":"usc","label":"18 U.S.C. § 3292","url":"https://www.law.cornell.edu/uscode/text/18/3292","subs":["(a)(1)","(a)(2)","(b)"],"stext":{"head":"§3292. Suspension of limitations to permit United States to obtain foreign evidence","paras":[[0,"(a)(1) Upon application of the United States, filed before return of an indictment, indicating that evidence of an offense is in a foreign country, the district court before which a grand jury is impaneled to investigate the offense shall suspend the running of the statute of limitations for the offense if the court finds by a preponderance of the evidence that an official request has been made for such evidence and that it reasonably appears, or reasonably appeared at the time the request was made, that such evidence is, or was, in such foreign country."],[0,"(2) The court shall rule upon such application not later than thirty days after the filing of the application."],[0,"(b) Except as provided in subsection (c) of this section, a period of suspension under this section shall begin on the date on which the official request is made and end on the date on which the foreign court or authority takes final action on the request."],[0,"(c) The total of all periods of suspension under this section with respect to an offense—"],[1,"(1) shall not exceed three years; and"],[1,"(2) shall not extend a period within which a criminal case must be initiated for more than six months if all foreign authorities take final action before such period would expire without regard to this section."],[0,"(d) As used in this section, the term \"official request\" means a letter rogatory, a request under a treaty or convention, or any other request for evidence made by a court of the United States or an authority of the United States having criminal law enforcement responsibility, to a court or other authority of a foreign country."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3292?type=usc&year=mostrecent&link-type=html"},"head":"§3292. Suspension of limitations to permit United States to obtain foreign evidence","tname":"Crimes and Criminal Procedure","by":{"1":"33, 34, 34, 34, 33","2":"21, 22, 21, 22"}},{"t":"law","label":"Pub. L. No. 99-646","url":"https://www.govinfo.gov/link/statute/100/3595","by":{"1":"22"}},{"t":"usc","label":"15 U.S.C. § 78j","url":"https://www.law.cornell.edu/uscode/text/15/78j","subs":["(b)"],"stext":{"head":"§78j. Manipulative and deceptive devices","paras":[[0,"It shall be unlawful for any person, directly or indirectly, by the use of any means or instrumentality of interstate commerce or of the mails, or of any facility of any national securities exchange—"],[1,"(a)(1) To effect a short sale, or to use or employ any stop-loss order in connection with the purchase or sale, of any security other than a government security, in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Paragraph (1) of this subsection shall not apply to security futures products."],[1,"(b) To use or employ, in connection with the purchase or sale of any security registered on a national securities exchange or any security not so registered, or any securities-based swap agreement 1 any manipulative or deceptive device or contrivance in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(c)(1) To effect, accept, or facilitate a transaction involving the loan or borrowing of securities in contravention of such rules and regulations as the Commission may prescribe as necessary or appropriate in the public interest or for the protection of investors."],[1,"(2) Nothing in paragraph (1) may be construed to limit the authority of the appropriate Federal banking agency (as defined in section 1813(q) of title 12), the National Credit Union Administration, or any other Federal department or agency having a responsibility under Federal law to prescribe rules or regulations restricting transactions involving the loan or borrowing of securities in order to protect the safety and soundness of a financial institution or to protect the financial system from systemic risk."],[0,"Rules promulgated under subsection (b) that prohibit fraud, manipulation, or insider trading (but not rules imposing or specifying reporting or recordkeeping requirements, procedures, or standards as prophylactic measures against fraud, manipulation, or insider trading), and judicial precedents decided under subsection (b) and rules promulgated thereunder that prohibit fraud, manipulation, or insider trading, shall apply to security-based swap agreements to the same extent as they apply to securities. Judicial precedents decided under section 77q(a) of this title and sections 78i, 78o, 78p, 78t, and 78u–1 of this title, and judicial precedents decided under applicable rules promulgated under such sections, shall apply to security-based swap agreements to the same extent as they apply to securities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78j?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§78j. Manipulative and deceptive devices","tname":"Commerce and Trade","by":{"1":"19"}},{"t":"usc","label":"18 U.S.C. § 3551","url":"https://www.law.cornell.edu/uscode/text/18/3551","by":{"1":"42"}},{"t":"usc","label":"18 U.S.C. § 3552","url":"https://www.law.cornell.edu/uscode/text/18/3552","by":{"1":"43"}},{"t":"usc","label":"18 U.S.C. § 3562","url":"https://www.law.cornell.edu/uscode/text/18/3562","subs":["(b)"],"by":{"1":"24, 43"}},{"t":"usc","label":"18 U.S.C. § 3563","url":"https://www.law.cornell.edu/uscode/text/18/3563","subs":["(b)(1)","(b)(4)","(b)(7)","(b)(8)"],"by":{"1":"24, 24, 24, 25"}},{"t":"usc","label":"18 U.S.C. § 3572","url":"https://www.law.cornell.edu/uscode/text/18/3572","subs":["(b)","(c)"],"by":{"1":"20, 43"}},{"t":"usc","label":"18 U.S.C. § 3582","url":"https://www.law.cornell.edu/uscode/text/18/3582","subs":["(a)","(b)","(c)(2)","(d)"],"by":{"1":"43, 43, 3, 42"}},{"t":"usc","label":"18 U.S.C. § 3584","url":"https://www.law.cornell.edu/uscode/text/18/3584","subs":["(a)"],"by":{"1":"29"}},{"t":"usc","label":"18 U.S.C. § 3603","url":"https://www.law.cornell.edu/uscode/text/18/3603","subs":["(1)"],"stext":{"head":"§3603. Duties of probation officers","paras":[[0,"A probation officer shall—"],[1,"(1) instruct a probationer or a person on supervised release, who is under his supervision, as to the conditions specified by the sentencing court, and provide him with a written statement clearly setting forth all such conditions;"],[1,"(2) keep informed, to the degree required by the conditions specified by the sentencing court, as to the conduct and condition of a probationer or a person on supervised release, who is under his supervision, and report his conduct and condition to the sentencing court;"],[1,"(3) use all suitable methods, not inconsistent with the conditions specified by the court, to aid a probationer or a person on supervised release who is under his supervision, and to bring about improvements in his conduct and condition;"],[1,"(4) be responsible for the supervision of any probationer or a person on supervised release who is known to be within the judicial district;"],[1,"(5) keep a record of his work, and make such reports to the Director of the Administrative Office of the United States Courts as the Director may require;"],[1,"(6) upon request of the Attorney General or his designee, assist in the supervision of and furnish information about, a person within the custody of the Attorney General while on work release, furlough, or other authorized release from his regular place of confinement, or while in prerelease custody pursuant to the provisions of section 3624(c);"],[1,"(7) keep informed concerning the conduct, condition, and compliance with any condition of probation, including the payment of a fine or restitution of each probationer under his supervision and report thereon to the court placing such person on probation and report to the court any failure of a probationer under his supervision to pay a fine in default within thirty days after notification that it is in default so that the court may determine whether probation should be revoked;"],[1,"(8)(A) when directed by the court, and to the degree required by the regimen of care or treatment ordered by the court as a condition of release, keep informed as to the conduct and provide supervision of a person conditionally released under the provisions of section 4243, 4246, or 4248 of this title, and report such person's conduct and condition to the court ordering release and to the Attorney General or his designee; and"],[1,"(B) immediately report any violation of the conditions of release to the court and the Attorney General or his designee;"],[1,"(9) if approved by the district court, be authorized to carry firearms under such rules and regulations as the Director of the Administrative Office of the United States Courts may prescribe; and"],[1,"(10) perform any other duty that the court may designate."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3603?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3603. Duties of probation officers","tname":"Crimes and Criminal Procedure","by":{"1":"5"}},{"t":"usc","label":"18 U.S.C. § 3606","url":"https://www.law.cornell.edu/uscode/text/18/3606","stext":{"head":"§3606. Arrest and return of a probationer","paras":[[0,"If there is probable cause to believe that a probationer or a person on supervised release has violated a condition of his probation or release, he may be arrested, and, upon arrest, shall be taken without unnecessary delay before the court having jurisdiction over him. A probation officer may make such an arrest wherever the probationer or releasee is found, and may make the arrest without a warrant. The court having supervision of the probationer or releasee, or, if there is no such court, the court last having supervision of the probationer or releasee, may issue a warrant for the arrest of a probationer or releasee for violation of a condition of release, and a probation officer or United States marshal may execute the warrant in the district in which the warrant was issued or in any district in which the probationer or releasee is found."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3606?type=usc&year=mostrecent&link-type=html"},"op":1,"sum":"Explaining that the District Court “may issue a warrant for the arrest” of the releasee for “violation of a condition of release”.","sumSrc":"opinion","head":"§3606. Arrest and return of a probationer","tname":"Crimes and Criminal Procedure","by":{"1":"6"}},{"t":"usc","label":"18 U.S.C. § 3607","url":"https://www.law.cornell.edu/uscode/text/18/3607","subs":["(a)"],"by":{"1":"43"}},{"t":"usc","label":"18 U.S.C. § 3613","url":"https://www.law.cornell.edu/uscode/text/18/3613","subs":["(a)","(b)(1)"],"by":{"1":"43, 43"}},{"t":"usc","label":"18 U.S.C. § 3621","url":"https://www.law.cornell.edu/uscode/text/18/3621","subs":["(e)(2)(B)"],"stext":{"head":"§3621. Imprisonment of a convicted person","paras":[[0,"(a) Commitment to Custody of Bureau of Prisons.—A person who has been sentenced to a term of imprisonment pursuant to the provisions of subchapter D of chapter 227 shall be committed to the custody of the Bureau of Prisons until the expiration of the term imposed, or until earlier released for satisfactory behavior pursuant to the provisions of section 3624."],[0,"(b) Place of Imprisonment.—The Bureau of Prisons shall designate the place of the prisoner's imprisonment, and shall, subject to bed availability, the prisoner's security designation, the prisoner's programmatic needs, the prisoner's mental and medical health needs, any request made by the prisoner related to faith-based needs, recommendations of the sentencing court, and other security concerns of the Bureau of Prisons, place the prisoner in a facility as close as practicable to the prisoner's primary residence, and to the extent practicable, in a facility within 500 driving miles of that residence. The Bureau shall, subject to consideration of the factors described in the preceding sentence and the prisoner's preference for staying at his or her current facility or being transferred, transfer prisoners to facilities that are closer to the prisoner's primary residence even if the prisoner is already in a facility within 500 driving miles of that residence. The Bureau may designate any available penal or correctional facility that meets minimum standards of health and habitability established by the Bureau, whether maintained by the Federal Government or otherwise and whether within or without the judicial district in which the person was convicted, that the Bureau determines to be appropriate and suitable, considering—"],[1,"(1) the resources of the facility contemplated;"],[1,"(2) the nature and circumstances of the offense;"],[1,"(3) the history and characteristics of the prisoner;"],[1,"(4) any statement by the court that imposed the sentence—"],[2,"(A) concerning the purposes for which the sentence to imprisonment was determined to be warranted; or"],[2,"(B) recommending a type of penal or correctional facility as appropriate; and"],[1,"(5) any pertinent policy statement issued by the Sentencing Commission pursuant to section 994(a)(2) of title 28."],[0,"In designating the place of imprisonment or making transfers under this subsection, there shall be no favoritism given to prisoners of high social or economic status. The Bureau may at any time, having regard for the same matters, direct the transfer of a prisoner from one penal or correctional facility to another. The Bureau shall make available appropriate substance abuse treatment for each prisoner the Bureau determines has a treatable condition of substance addiction or abuse. Any order, recommendation, or request by a sentencing court that a convicted person serve a term of imprisonment in a community corrections facility shall have no binding effect on the authority of the Bureau under this section to determine or change the place of imprisonment of that person. Notwithstanding any other provision of law, a designation of a place of imprisonment under this subsection is not reviewable by any court."],[0,"(c) Delivery of Order of Commitment.—When a prisoner, pursuant to a court order, is placed in the custody of a person in charge of a penal or correctional facility, a copy of the order shall be delivered to such person as evidence of this authority to hold the prisoner, and the original order, with the return endorsed thereon, shall be returned to the court that issued it."],[0,"(d) Delivery of Prisoner for Court Appearances.—The United States marshal shall, without charge, bring a prisoner into court or return him to a prison facility on order of a court of the United States or on written request of an attorney for the Government."],[0,"(e) Substance Abuse Treatment.—"],[1,"(1) Phase-in.—In order to carry out the requirement of the last sentence of subsection (b) of this section, that every prisoner with a substance abuse problem have the opportunity to participate in appropriate substance abuse treatment, the Bureau of Prisons shall, subject to the availability of appropriations, provide residential substance abuse treatment (and make arrangements for appropriate aftercare)—"],[2,"(A) for not less than 50 percent of eligible prisoners by the end of fiscal year 1995, with priority for such treatment accorded based on an eligible prisoner's proximity to release date;"],[2,"(B) for not less than 75 percent of eligible prisoners by the end of fiscal year 1996, with priority for such treatment accorded based on an eligible prisoner's proximity to release date; and"],[2,"(C) for all eligible prisoners by the end of fiscal year 1997 and thereafter, with priority for such treatment accorded based on an eligible prisoner's proximity to release date."],[1,"(2) Incentive for prisoners' successful completion of treatment program.—"],[2,"(A) Generally.—Any prisoner who, in the judgment of the Director of the Bureau of Prisons, has successfully completed a program of residential substance abuse treatment provided under paragraph (1) of this subsection, shall remain in the custody of the Bureau under such conditions as the Bureau deems appropriate. If the conditions of confinement are different from those the prisoner would have experienced absent the successful completion of the treatment, the Bureau shall periodically test the prisoner for substance abuse and discontinue such conditions on determining that substance abuse has recurred."],[2,"(B) Period of custody.—The period a prisoner convicted of a nonviolent offense remains in custody after successfully completing a treatment program may be reduced by the Bureau of Prisons, but such reduction may not be more than one year from the term the prisoner must otherwise serve."],[1,"(3) Report.—The Bureau of Prisons shall transmit to the Committees on the Judiciary of the Senate and the House of Representatives on January 1, 1995, and on January 1 of each year thereafter, a report. Such report shall contain—"],[2,"(A) a detailed quantitative and qualitative description of each substance abuse treatment program, residential or not, operated by the Bureau;"],[2,"(B) a full explanation of how eligibility for such programs is determined, with complete information on what proportion of prisoners with substance abuse problems are eligible; and"],[2,"(C) a complete statement of to what extent the Bureau has achieved compliance with the requirements of this title."],[1,"(4) Authorization of appropriations.—There are authorized to carry out this subsection such sums as may be necessary for each of fiscal years 2007 through 2011."],[1,"(5) Definitions.—As used in this subsection—"],[2,"(A) the term \"residential substance abuse treatment\" means a course of individual and group activities and treatment, lasting at least 6 months, in residential treatment facilities set apart from the general prison population (which may include the use of pharmocotherapies,1 where appropriate, that may extend beyond the 6-month period);"],[2,"(B) the term \"eligible prisoner\" means a prisoner who is—"],[3,"(i) determined by the Bureau of Prisons to have a substance abuse problem; and"],[3,"(ii) willing to participate in a residential substance abuse treatment program; and"],[2,"(C) the term \"aftercare\" means placement, case management and monitoring of the participant in a community-based substance abuse treatment program when the participant leaves the custody of the Bureau of Prisons."],[1,"(6) Coordination of federal assistance.—The Bureau of Prisons shall consult with the Department of Health and Human Services concerning substance abuse treatment and related services and the incorporation of applicable components of existing comprehensive approaches including relapse prevention and aftercare services."],[1,"(7) Eligibility of primary caretaker parents and pregnant women.—The Director of the Bureau of Prisons may not prohibit an eligible prisoner who is a primary caretaker parent (as defined in section 4051) or pregnant from participating in a program of residential substance abuse treatment provided under paragraph (1) on the basis of a failure by the eligible prisoner, before being committed to the custody of the Bureau of Prisons, to disclose to any official of the Bureau of Prisons that the prisoner had a substance abuse problem on or before the date on which the eligible prisoner was committed to the custody of the Bureau of Prisons."],[0,"(f) Sex Offender Management.—"],[1,"(1) In general.—The Bureau of Prisons shall make available appropriate treatment to sex offenders who are in need of and suitable for treatment, as follows:"],[2,"(A) Sex offender management programs.—The Bureau of Prisons shall establish non-residential sex offender management programs to provide appropriate treatment, monitoring, and supervision of sex offenders and to provide aftercare during pre-release custody."],[2,"(B) Residential sex offender treatment programs.—The Bureau of Prisons shall establish residential sex offender treatment programs to provide treatment to sex offenders who volunteer for such programs and are deemed by the Bureau of Prisons to be in need of and suitable for residential treatment."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/3621?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3621. Imprisonment of a convicted person","tname":"Crimes and Criminal Procedure","by":{"1":"35"}},{"t":"usc","label":"18 U.S.C. § 3622","url":"https://www.law.cornell.edu/uscode/text/18/3622","by":{"1":"35"}},{"t":"usc","label":"18 U.S.C. § 5037","url":"https://www.law.cornell.edu/uscode/text/18/5037","subs":["(b)","(c)"],"by":{"1":"42, 42"}},{"t":"usc","label":"28 U.S.C. § 994","url":"https://www.law.cornell.edu/uscode/text/28/994","subs":["(a)(1)(A)","(h)(1)","(l)(1)"],"by":{"1":"43, 42, 42"}},{"t":"usc","label":"18 U.S.C. § 1074","url":"https://www.law.cornell.edu/uscode/text/18/1074","subs":["(a)"],"by":{"1":"20"}},{"t":"usc","label":"20 U.S.C. § 6472","url":"https://www.law.cornell.edu/uscode/text/20/6472","subs":["(1)"],"by":{"1":"20"}},{"t":"usc","label":"29 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/29/504","subs":["(d)"],"by":{"1":"20"}},{"t":"usc","label":"38 U.S.C. § 3103","url":"https://www.law.cornell.edu/uscode/text/38/3103","subs":["(b)(3)"],"stext":{"head":"§3103. Periods of eligibility","paras":[[0,"(a) Except as provided in subsection (b), (c), (d), (e), (g), or (h) 1 of this section, a rehabilitation program may not be afforded to a veteran under this chapter after the end of the twelve-year period beginning on the date of such veteran's discharge or release from active military, naval, air, or space service."],[0,"(b)(1) In any case in which the Secretary determines that a veteran has been prevented from participating in a vocational rehabilitation program under this chapter within the period of eligibility prescribed in subsection (a) of this section because a medical condition of such veteran made it infeasible for such veteran to participate in such a program, the twelve-year period of eligibility shall not run during the period of time that such veteran was so prevented from participating in such a program, and such period of eligibility shall again begin to run on the first day following such veteran's recovery from such condition on which it is reasonably feasible, as determined under regulations which the Secretary shall prescribe, for such veteran to participate in such a program."],[0,"(2) In any case in which the Secretary determines that a veteran has been prevented from participating in a vocational rehabilitation program under this chapter within the period of eligibility prescribed in subsection (a) of this section because—"],[1,"(A) such veteran had not met the requirement of a discharge or release from active military, naval, air, or space service under conditions other than dishonorable before (i) the nature of such discharge or release was changed by appropriate authority, or (ii) the Secretary determined, under regulations prescribed by the Secretary, that such discharge or release was under conditions other than dishonorable, or"],[1,"(B) such veteran's discharge or dismissal was, under section 5303 of this title, a bar to benefits under this title before the Secretary made a determination that such discharge or dismissal is not a bar to such benefits,"],[0,"the twelve-year period of eligibility shall not run during the period of time that such veteran was so prevented from participating in such a program."],[0,"(3) In any case in which the Secretary determines that a veteran has been prevented from participating in a vocational rehabilitation program under this chapter within the period of eligibility prescribed in subsection (a) of this section because such veteran had not established the existence of a service-connected disability rated at 10 percent or more, the twelve-year period of eligibility shall not run during the period such veteran was so prevented from participating in such a program."],[0,"(c) In any case in which the Secretary determines that a veteran is in need of services to overcome a serious employment handicap, such veteran may be afforded a vocational rehabilitation program after the expiration of the period of eligibility otherwise applicable to such veteran if the Secretary also determines, on the basis of such veteran's current employment handicap and need for such services, that an extension of the applicable period of eligibility is necessary for such veteran and—"],[1,"(1) that such veteran had not previously been rehabilitated to the point of employability;"],[1,"(2) that such veteran had previously been rehabilitated to the point of employability but (A) the need for such services had arisen out of a worsening of such veteran's service-connected disability that precludes such veteran from performing the duties of the occupation for which such veteran was previously trained in a vocational rehabilitation program under this chapter, or (B) the occupation for which such veteran had been so trained is not suitable in view of such veteran's current employment handicap and capabilities; or"],[1,"(3) under regulations which the Secretary shall prescribe, that an extension of the period of eligibility of such veteran is necessary to accomplish the purposes of a rehabilitation program for such veteran."],[0,"(d) In any case in which the Secretary has determined that a veteran's disability or disabilities are so severe that the achievement of a vocational goal currently is not reasonably feasible, such veteran may be afforded a program of independent living services and assistance in accordance with the provisions of section 3120 of this title after the expiration of the period of eligibility otherwise applicable to such veteran if the Secretary also determines that an extension of the period of eligibility of such veteran is necessary for such veteran to achieve maximum independence in daily living."],[0,"(e)(1) The limitation in subsection (a) shall not apply to a rehabilitation program described in paragraph (2)."],[0,"(2) A rehabilitation program described in this paragraph is a rehabilitation program pursued by a veteran under section 3102(b) of this title."],[0,"(f) In any case in which the Secretary has determined that a veteran was prevented from participating in a vocational rehabilitation program under this chapter within the period of eligibility otherwise prescribed in this section as a result of being ordered to serve on active duty under section 688, 12301(a), 12301(d), 12301(g), 12302, 12304, 12304a, or 12304b of title 10, such period of eligibility shall not run for the period of such active duty service plus four months."],[0,"(g) Subsection (a) shall not apply to a veteran who was discharged or released from active military, naval, or air service on or after January 1, 2013."],[0,"(h)(1) 2 In the case of a veteran who is eligible for a vocational rehabilitation program under this chapter and who is prevented from participating in the vocational rehabilitation program within the period of eligibility prescribed in subsection (a) because of a covered reason, as determined by the Secretary, such period of eligibility—"],[1,"(A) shall not run during the period the veteran is so prevented from participating in such program; and"],[1,"(B) shall again begin running on a date determined by the Secretary that is—"],[2,"(i) not earlier than the first day after the veteran is able to resume participation in a vocational rehabilitation program under this chapter; and"],[2,"(ii) not later than 90 days after that day."],[0,"(2) In this subsection, a covered reason is—"],[1,"(A) the temporary or permanent closure of an educational institution by reason of an emergency situation; or"],[1,"(B) another reason that prevents the veteran from participating in the vocational rehabilitation program, as determined by the Secretary."],[0,"(h)2 In any case in which the Secretary determines that a veteran has been prevented from participating in a vocational rehabilitation program under this chapter within the 12-year period of eligibility prescribed in subsection (a) due to an emergency situation, such 12-year period—"],[1,"(1) shall not run during the period the individual is so prevented from participating 3 such program; and"],[1,"(2) shall again begin running on the first day after the individual is able to resume participation in such program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/38/3103?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3103. Periods of eligibility","tname":"Veterans' Benefits","by":{"1":"33"}},{"t":"case","label":"Bailey v. United States","cite":"516 U.S. 137","y":1995,"id":"1995/94-7448","sc":1,"sum":"The proximity and accessibility test for \"use\" is so broad that no independent role remains for \"carry.\" \"Use\" in Section 924(c)(1) requires more than proximity and accessibility that might embolden a defendant. It requires active employment of the firearm by the defendant, making the firearm an operative factor in relation to the predicate offense.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Barber v. Thomas","cite":"560 U.S. 474","y":2010,"id":"2009/09-5201","sc":1,"op":2,"sum":"The Court held that the Federal Bureau of Prisons' method of determining \"good behavior,\" which was based on the inmate's time in prison rather than the overall sentence, was constitutional.","sumSrc":"Oyez","by":{"2":"9, 10, 11"}},{"t":"case","label":"Brown v. Gardner","cite":"513 U.S. 115","y":1994,"id":"1994/93-1128","sc":1,"sum":"The Court affirmed the lower court's decision and ruled for Gardner. The Court held that Section 1151 contains no language requiring proof of fault, and it rejected the Government's claims that the requirement was implicit in the language of the statute.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Burns v. United States","cite":"287 U.S. 216","y":1932,"id":"scdb/1932-006","sc":1,"op":1,"sum":"Noting that a probationer is still “subject to the conditions of ” probation “even in jail”.","sumSrc":"opinion","by":{"2":"17"}},{"t":"case","label":"King v. St. Vincent’s Hospital","cite":"502 U.S. 215","y":1991,"id":"1991/90-889","sc":1,"sum":"Section 2024(d) does not limit the length of military service after which a member of the Armed Forces retains a right to civilian reemployment. Subsection (d)'s text-which specifies that any covered employee \"shall... be granted a leave... for the period required to perform active duty [and] [u]pon... release from... such duty... shall be permitted to return to [his or her] position\"-is utterly silent about any …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"usc","label":"18 U.S.C. § 1344","url":"https://www.law.cornell.edu/uscode/text/18/1344","by":{"2":"11"}},{"t":"usc","label":"18 U.S.C. § 3042","url":"https://www.law.cornell.edu/uscode/text/18/3042","by":{"2":"13"}},{"t":"usc","label":"18 U.S.C. § 3145","url":"https://www.law.cornell.edu/uscode/text/18/3145","subs":["(c)"],"by":{"2":"25"}},{"t":"usc","label":"18 U.S.C. § 3623","url":"https://www.law.cornell.edu/uscode/text/18/3623","by":{"2":"6"}},{"t":"usc","label":"18 U.S.C. § 3731","url":"https://www.law.cornell.edu/uscode/text/18/3731","by":{"2":"24"}},{"t":"usc","label":"18 U.S.C. § 4002","url":"https://www.law.cornell.edu/uscode/text/18/4002","by":{"2":"11"}},{"t":"usc","label":"18 U.S.C. § 4106A","url":"https://www.law.cornell.edu/uscode/text/18/4106A","subs":["(b)(2)(A)"],"by":{"2":"12"}},{"t":"usc","label":"18 U.S.C. § 4245","url":"https://www.law.cornell.edu/uscode/text/18/4245","by":{"2":"12"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(a)"],"by":{"2":"25"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(a)"],"by":{"2":"25"}}]};